import os
import re
from collections import defaultdict

REPO = "/bench/repo"

# Data layer paths (directories whose packages should be excluded)
DATA_LAYER_PREFIXES = [
    "store/",
    "proto/gen/store/",
    "proto/store/",  # proto files, not go but exclude anyway
]

def is_data_layer(rel_path):
    for prefix in DATA_LAYER_PREFIXES:
        if rel_path.startswith(prefix) or rel_path == prefix.rstrip('/'):
            return True
    return False

def get_go_package(filepath):
    """Return package path like server/router/api/v1 from file path"""
    rel = filepath[len(REPO)+1:]
    if not rel.endswith('.go'):
        return None
    return os.path.dirname(rel)

# Step 1: Identify persistent entity types from store/*.go root files
entity_types = set()
entity_def_files = {}
store_root = os.path.join(REPO, "store")
for fname in os.listdir(store_root):
    if not fname.endswith('.go') or fname.endswith('_test.go'):
        continue
    fpath = os.path.join(store_root, fname)
    with open(fpath) as f:
        content = f.read()
    # Find main entity structs - those with Create/Find methods pattern
    # Look for "type X struct {" at start of line
    for m in re.finditer(r'^type (\w+) struct \{', content, re.MULTILINE):
        name = m.group(1)
        # Exclude helper/query structs
        if name.startswith('Find') or name.startswith('Update') or name.startswith('Delete'):
            continue
        if name in ('Store', 'deploymentConfiguration'):
            continue
        if 'Failpoint' in name or name.endswith('Result'):
            continue
        entity_types.add(name)
        entity_def_files.setdefault(name, []).append(f"store/{fname}")

# Also from proto/store
proto_store = os.path.join(REPO, "proto/store")
for fname in os.listdir(proto_store):
    if fname.endswith('.proto'):
        entity_def_files.setdefault(fname.replace('.proto','').title().replace('_',''), [])

print("Entity types from store/*.go:")
for e in sorted(entity_types):
    print(f"  {e}: {entity_def_files.get(e, [])}")

# Step 2: Scan all Go files for store.<Entity> references
pkg_refs = defaultdict(set)  # entity -> set of packages

# Pattern: store.EntityName (word boundary after)
for root, dirs, files in os.walk(REPO):
    # skip .git
    if '.git' in root:
        continue
    for fname in files:
        if not fname.endswith('.go'):
            continue
        fpath = os.path.join(root, fname)
        rel = fpath[len(REPO)+1:]
        if is_data_layer(rel):
            continue
        pkg = get_go_package(fpath)
        with open(fpath) as f:
            content = f.read()
        for entity in entity_types:
            # Match store.Entity as type reference
            pattern = r'\bstore\.' + re.escape(entity) + r'\b'
            if re.search(pattern, content):
                pkg_refs[entity].add(pkg)

print("\n=== Package counts per entity (external to data layer) ===")
ranked = sorted(pkg_refs.items(), key=lambda x: (-len(x[1]), x[0]))
for entity, pkgs in ranked:
    print(f"\n{entity}: {len(pkgs)} packages")
    for p in sorted(pkgs):
        print(f"  - {p}")

