use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = "/bench/repo";

my @DATA_PREFIXES = ("store/", "proto/gen/store/", "proto/store/");

sub is_data_layer {
    my ($rel) = @_;
    for my $p (@DATA_PREFIXES) {
        return 1 if index($rel, $p) == 0;
    }
    return 0;
}

# Identify entity types from store/*.go
my %entities;
my %entity_files;
opendir(my $dh, "$REPO/store") or die $!;
for my $f (readdir $dh) {
    next unless $f =~ /\.go$/ && $f !~ /_test\.go$/;
    open my $fh, "<", "$REPO/store/$f" or die $!;
    my $content = do { local $/; <$fh> };
    close $fh;
    while ($content =~ /^type (\w+) struct \{/mg) {
        my $name = $1;
        next if $name =~ /^(Find|Update|Delete)/;
        next if $name =~ /Failpoint|Result$/;
        next if $name =~ /^(Store|deploymentConfiguration)$/;
        $entities{$name} = 1;
        push @{$entity_files{$name}}, "store/$f";
    }
}

print "Persistent entity types (store/*.go):\n";
for my $e (sort keys %entities) {
    print "  $e -> ", join(", ", @{$entity_files{$e}}), "\n";
}

# Scan references
my %pkg_refs;  # entity -> {pkg => 1}

find({
    wanted => sub {
        return unless /\.go$/;
        my $fpath = $File::Find::name;
        my $rel = substr($fpath, length($REPO) + 1);
        return if is_data_layer($rel);
        return if $rel =~ m{^\.git/};
        open my $fh, "<", $fpath or return;
        my $content = do { local $/; <$fh> };
        close $fh;
        my $pkg = dirname($rel);
        for my $entity (keys %entities) {
            if ($content =~ /\bstore\.\Q$entity\E\b/) {
                $pkg_refs{$entity}{$pkg} = 1;
            }
        }
    },
    no_chdir => 1,
}, $REPO);

print "\n=== External package reference counts ===\n";
my @ranked = sort { scalar(keys %{$pkg_refs{$b}}) <=> scalar(keys %{$pkg_refs{$a}}) || $a cmp $b } keys %entities;
for my $entity (@ranked) {
    my @pkgs = sort keys %{$pkg_refs{$entity}};
    printf "%s: %d packages\n", $entity, scalar @pkgs;
    for my $p (@pkgs) {
        print "  - $p\n";
    }
    print "\n";
}
'

